import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('los-desiertos', 'C',
 [dict(t=488, e=540, titulo='Los desiertos son necesarios', txt='Los desiertos son necesarios. Los desiertos en la Biblia son tipo de problemas, y hay unos peores que otros. El pueblo de Israel, cuando salió de Egipto para ir a tomar posesión de la tierra que emana leche y miel, es decir, la vida en abundancia, Canaán, tuvo que atravesar siete desiertos. Entonces, nadie va a poder llegar a la vida en abundancia si antes no camina por los problemas, por el desierto, porque es una cámara de descompresión donde nos preparan para poder recibir las bendiciones que Dios tiene para nosotros.'),
  dict(t=2928, e=2985, titulo='La chusma que quiere volver a la esclavitud', txt='¿De dónde había sacado Dios al pueblo de Israel? De la esclavitud. ¿Qué es lo que quiere la chusma que viene con el pueblo, o los extranjeros, como decía en la otra versión? Volver a llevar a la gente a la esclavitud que tenía antes. […] ¿En qué manera podría volvernos a esclavizar? Primero preguntémonos de qué esclavitud nos sacó el Señor. Nos sacó de la esclavitud del pecado.'),
  dict(t=3627, e=3680, titulo='Con quién te relacionas', txt='¿No dice la Biblia que las malas compañías echan a perder las buenas costumbres? Entonces, si tú te estás preparando para el encuentro con el Señor, tienes que cuidar con quién te relacionas dentro de la iglesia. En el mundo ya se sabe […], pero aquí uno baja la guardia. Y tenemos que tener cuidado de no terminar en esta categoría.')],
 [dict(t=575, txt='No es que el desierto cambie a las personas, pero sí el desierto trae entendimiento.'),
  dict(t=2208, txt='La prueba viene para ver cómo reaccionamos. Dios nos está observando.'),
  dict(t=4140, txt='Ahora entiendo que los desiertos son necesarios para quitar toda la escoria que yo traía.')],
 ['¿Qué «desierto» estás atravesando y qué crees que Dios te quiere enseñar en él?',
  '¿Hay alguna compañía dentro o fuera de la iglesia que hoy necesitas entregarle a Dios?',
  'Si la prueba viene para ver cómo reaccionamos, ¿cómo has estado reaccionando tú?'])
